<?php
require_once dirname(__DIR__) . '/app/bootstrap.php';require_once dirname(__DIR__) . '/app/layout.php';require_login();
$q=trim((string)($_GET['q']??''));$params=[];$where='1=1';if($q!==''){$where='(p.product_name LIKE ? OR a.field_name LIKE ? OR u.username LIKE ?)';$params=array_fill(0,3,"%$q%");}
$s=db()->prepare("SELECT a.*,u.username,p.product_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN products p ON p.id=a.product_id WHERE $where ORDER BY a.created_at DESC LIMIT 500");$s->execute($params);$logs=$s->fetchAll();page_header('Audit log');?>
<div class="page-title"><h1>Audit log</h1></div><form class="toolbar card"><input name="q" value="<?=e($q)?>" placeholder="Filter by product, field or user"><button class="button">Filter</button></form><div class="card table-wrap"><table><thead><tr><th>Date</th><th>User</th><th>Product</th><th>Action</th><th>Field</th><th>Old</th><th>New</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['username']??'System')?></td><td><?=e($l['product_name']??'—')?></td><td><?=e($l['action'])?></td><td><?=e($l['field_name']??'—')?></td><td><?=e($l['old_value']??'—')?></td><td><?=e($l['new_value']??'—')?></td></tr><?php endforeach?></tbody></table></div><?php page_footer();?>
